table([['<b>Atualização principal</b>','<b>Situação nesta edição</b>'],['SINAN e LIRAa','<b>ATENDE por confirmação do responsável.</b> A origem da classificação fica identificada nos itens diretamente relacionados.'],['Segurança e integridade','Novas equipes UVIS herdam a prefeitura; controle de edição, inatividade e recuperação de transações incorporados ao acompanhamento.'],['Consultas personalizadas','Catálogo pessoal, campos, fórmulas, filtros, condições, exceções, agrupamento, mapa, tabela, PDF e Excel implementados.'],['E-mail por prefeitura','Destinatário municipal e fluxo assistido disponíveis. O usuário anexa o PDF e envia no próprio aplicativo; envio direto depende de SMTP.']], [157,354])
